package io.mavsdk.kotlin.plugins.mavlink_direct

import kotlin.coroutines.resume
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow
import kotlinx.coroutines.suspendCancellableCoroutine

/** Enable direct MAVLink communication using libmav. */
class MavlinkDirect internal constructor(private val native: MavlinkDirectNative) {
    private var closed = false

    /** Possible results returned for action requests. */
    enum class Result(val value: Int) {
        /** Unknown result */
        UNKNOWN(0),
        /** Request succeeded */
        SUCCESS(1),
        /** Error */
        ERROR(2),
        /** Invalid MAVLink message */
        INVALID_MESSAGE(3),
        /** Invalid field name or value */
        INVALID_FIELD(4),
        /** Connection error */
        CONNECTION_ERROR(5),
        /** No system connected */
        NO_SYSTEM(6),
        /** Request timed out */
        TIMEOUT(7);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    /**
     * A complete MAVLink message with all header information and fields
     *
     * @property messageName MAVLink message name (e.g., "HEARTBEAT", "GLOBAL_POSITION_INT")
     * @property systemId System ID of the sender (for received messages)
     * @property componentId Component ID of the sender (for received messages)
     * @property targetSystemId Target system ID (for sending, 0 for broadcast)
     * @property targetComponentId Target component ID (for sending, 0 for broadcast)
     * @property fieldsJson All message fields as single JSON object
     */
    data class MavlinkMessage(
        val messageName: String,
        val systemId: Int,
        val componentId: Int,
        val targetSystemId: Int,
        val targetComponentId: Int,
        val fieldsJson: String,
    )

    /**
     * Send a MAVLink message directly to the system.
     *
     * This allows sending any MAVLink message with full control over the message content.
     *
     * @param message The MAVLink message to send
     * @return The result of the request.
     */
    fun sendMessage(message: MavlinkMessage): Result = Result.fromValue(native.sendMessage(message))

    /**
     * Subscribe to incoming MAVLink messages.
     *
     * This provides direct access to incoming MAVLink messages. Use an empty string in message_name
     * to subscribe to all messages, or specify a message name (e.g., "HEARTBEAT") to filter for
     * specific message types.
     *
     * @param messageName MAVLink message name to filter for (e.g., "HEARTBEAT"), empty string = all
     *   messages
     * @return The received MAVLink message
     */
    fun subscribeMessage(messageName: String): Flow<MavlinkMessage> = callbackFlow {
        val subscriptionHandle = native.subscribeMessage(messageName) { value -> trySend(value) }
        awaitClose { native.unsubscribeMessage(subscriptionHandle) }
    }

    /**
     * Load custom MAVLink message definitions from XML.
     *
     * This allows loading custom MAVLink message definitions at runtime, extending the available
     * message types beyond the built-in definitions.
     *
     * @param xmlContent The custom MAVLink XML definition content
     * @return The result of the request.
     */
    fun loadCustomXml(xmlContent: String): Result =
        Result.fromValue(native.loadCustomXml(xmlContent))

    /**
     * Send a command and wait for its final COMMAND_ACK.
     *
     * The command is a COMMAND_LONG or COMMAND_INT message with its fields as JSON, e.g.
     * message_name "COMMAND_LONG" and fields_json
     * {"target_system":1,"target_component":1,"command":400,"param1":1,...}.
     *
     * The command is retransmitted if no ack arrives. MAV_RESULT_IN_PROGRESS acks are handled
     * internally: the command is not retransmitted after one, and the call keeps waiting for the
     * final ack.
     *
     * RESULT_SUCCESS only means that a final COMMAND_ACK was received. Whether the command was
     * accepted is in the "result" field of the returned ack (MAV_RESULT, e.g. 0 for
     * MAV_RESULT_ACCEPTED, 2 for MAV_RESULT_DENIED). Any other result means no final ack was
     * received and the returned ack is empty.
     *
     * @param command COMMAND_LONG or COMMAND_INT message to send
     * @return The final COMMAND_ACK, check its "result" field (MAV_RESULT); only set on
     *   RESULT_SUCCESS
     */
    suspend fun sendCommand(command: MavlinkMessage): kotlin.Result<MavlinkMessage> =
        suspendCancellableCoroutine { continuation ->
            val callbackGuard = MavlinkDirectCallbackGuard()
            native.sendCommandAsync(command) { result, value ->
                val parsedResult = Result.fromValue(result)
                if (continuation.isActive && callbackGuard.tryClaim()) {
                    if (parsedResult == Result.SUCCESS) {
                        continuation.resume(kotlin.Result.success(value))
                    } else {
                        continuation.resume(
                            kotlin.Result.failure(
                                MavlinkDirectException(
                                    parsedResult,
                                    "sendCommand failed: ${parsedResult.name}",
                                )
                            )
                        )
                    }
                }
            }
        }

    internal fun destroy() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class MavlinkDirectException(val result: Result, message: String) : Exception(message)
}

internal interface MavlinkDirectNative {
    fun sendMessage(message: MavlinkDirect.MavlinkMessage): Int

    fun subscribeMessage(
        messageName: String,
        callback: (MavlinkDirect.MavlinkMessage) -> Unit,
    ): Long

    fun unsubscribeMessage(subscriptionHandle: Long)

    fun loadCustomXml(xmlContent: String): Int

    fun sendCommandAsync(
        command: MavlinkDirect.MavlinkMessage,
        callback: (Int, MavlinkDirect.MavlinkMessage) -> Unit,
    )

    fun destroy()
}

internal expect fun createMavlinkDirectNative(systemHandle: Long): MavlinkDirectNative

internal expect class MavlinkDirectCallbackGuard() {
    fun tryClaim(): Boolean
}
